// Candidate IDs are generated by the backend as DDMMYYYY + the day's order
// number, for example 2110202601 for the first candidate registered on
// 21 October 2026, then 2110202602, and 2210202601 the next day.
//
// - The date is the registration date in Asia/Colombo, not the server's.
// - The order number starts at 01 each day and has at least two digits. After
//   99 it simply gets a third digit (21102026100): the ID stays unique and
//   unambiguous because the first eight digits are always the date, and the
//   database allows 30 characters.
// - IDs are only ever allocated inside the transaction that saves the
//   candidate, so a failed registration uses no number and leaves no gap.
// - Allocation is serialised per day with a PostgreSQL advisory lock that is
//   held until the transaction ends. The unique index on lower(candidate_code)
//   remains the final safety net.
//
// Existing Candidate IDs (legacy ones such as 2008, or typed ones) are never
// read for any purpose except working out the next order number, and are
// never changed.

import { candidateCodeInUse } from './candidates.repository.js';

export const TIME_ZONE = 'Asia/Colombo';

// Arbitrary constant that names this lock family, so the per-day locks cannot
// clash with any other advisory lock in the application.
const LOCK_CLASS = 1_450_001;
// More than nine order digits cannot be a number this code produced.
const MAX_ORDER_DIGITS = 9;

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: TIME_ZONE,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

// The Asia/Colombo calendar date of a moment, as { day, month, year } strings.
export function colomboDate(now = new Date()) {
  const found = Object.fromEntries(parts.formatToParts(now).map((part) => [part.type, part.value]));
  return { day: found.day, month: found.month, year: found.year };
}

// "DDMMYYYY" for the Asia/Colombo date of the given moment.
export function candidateIdPrefix(now = new Date()) {
  const { day, month, year } = colomboDate(now);
  return `${day}${month}${year}`;
}

export function formatCandidateId(prefix, order) {
  return `${prefix}${String(order).padStart(2, '0')}`;
}

// The next free Candidate ID for the day, worked out the same way the real
// allocation does it. It only reads: nothing is reserved or saved, so the
// answer is a preview that another registration may take first.
export async function peekNextCandidateId(db, now = new Date()) {
  const prefix = candidateIdPrefix(now);
  const { rows } = await db.query(
    `SELECT max(substr(candidate_code, 9)::bigint) AS highest
       FROM candidates
      WHERE candidate_code ~ ('^' || $1 || '[0-9]{2,${MAX_ORDER_DIGITS}}$')`,
    [prefix],
  );
  let order = Number(rows[0].highest ?? 0) + 1;

  // The highest number is always free, but a case-insensitive clash with some
  // other typed value is still checked rather than assumed away.
  let candidateCode = formatCandidateId(prefix, order);
  while (await candidateCodeInUse(db, candidateCode)) {
    order += 1;
    candidateCode = formatCandidateId(prefix, order);
  }
  return candidateCode;
}

// The next free Candidate ID for the day, for real. Must be called inside the
// transaction that inserts the candidate (`db` is that transaction's client).
export async function allocateCandidateId(db, now = new Date()) {
  const prefix = candidateIdPrefix(now);

  // Two registrations on the same day take turns here. The lock is released
  // automatically when the transaction commits or rolls back.
  await db.query('SELECT pg_advisory_xact_lock($1::int, $2::int)', [
    LOCK_CLASS,
    Number(prefix.slice(4) + prefix.slice(2, 4) + prefix.slice(0, 2)),
  ]);
  return peekNextCandidateId(db, now);
}
